import { Request, Response } from "express";
import { catchAsync } from "../../utils/catchAsync";
import { AuthService } from "./auth.service";
import { sendResponse } from "../../utils/sendResponse";
import httpStatus from "http-status";
import { IRequestUser } from "../../interface";
import { AppError } from "../../utils/appError";
import { jwtUtils } from "../../utils/jwt";
import config from "../../config/env";
import { SignOptions } from "jsonwebtoken";
import { redirectUrl } from "../../utils/redirect";


const isProduction = config.node_env === "production";

const getAuthCookieOptions = (maxAge?: number) => ({
	httpOnly: true,
	secure: isProduction,
	sameSite: isProduction ? ("none" as const) : ("lax" as const),
	path: "/" as const,
	maxAge,
});



//& REGISTER USER
const registerOTP = catchAsync(async (req: Request, res: Response) => {
	const payload = req.body;
	await AuthService.registerOTP(payload);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "Register  OTP send successfully",
		data: null,
	});
});

//& VERIFY EMAIL
const verifyEmail = catchAsync(async (req: Request, res: Response) => {
	const payload = req.body;
	const result = await AuthService.verifyEmail(payload);

	const { accessToken, refreshToken, userCreated } = result;

	res.cookie("accessToken", accessToken, {
		httpOnly: true,
		secure: false,
		sameSite: "none",
		maxAge: 1000 * 60 * 60 * 24, // 24 hour or 1 day
	});
	res.cookie("refreshToken", refreshToken, {
		httpOnly: true,
		secure: false,
		sameSite: "none",
		maxAge: 1000 * 60 * 60 * 24 * 7, // 7 days
	});

	sendResponse(res, {
		statusCode: httpStatus.CREATED,
		success: true,
		message: "User created successfully",
		data: {
			accessToken,
			refreshToken,
			userCreated,
		},
	});
});

//& LOGIN USER
const loginUser = catchAsync(async (req: Request, res: Response) => {
	const payload = req.body;
	const result = await AuthService.loginUser(payload);
	const { user, accessToken, refreshToken } = result;

	res.cookie(
		"accessToken",
		accessToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24),
	);
	res.cookie(
		"refreshToken",
		refreshToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24 * 7),
	);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "User logged in successfully",
		data: {
			user,
			accessToken,
			refreshToken,
		},
	});
});

//& GET ME
const getMe = catchAsync(async (req: Request, res: Response) => {
	const user = req.user as unknown as IRequestUser;

	if (!user) {
		throw new AppError(
			httpStatus.UNAUTHORIZED,
			"User information is missing in the request",
		);
	}

	const result = await AuthService.getMe(user);
	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "User profile fetched successfully",
		data: result,
	});
});

//& CREATE ACCESS TOKEN
const refreshToken = catchAsync(async (req: Request, res: Response) => {
	if (!req.cookies.refreshToken) {
		throw new AppError(httpStatus.UNAUTHORIZED, "Refresh token is missing");
	}
	const result = await AuthService.refreshToken(req.cookies.refreshToken);
	const { accessToken, refreshToken: newRefreshToken } = result;

	res.cookie(
		"accessToken",
		accessToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24),
	);
	res.cookie(
		"refreshToken",
		refreshToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24 * 7),
	);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "New tokens generated successfully",
		data: {
			accessToken,
			refreshToken: newRefreshToken,
		},
	});
});

//& FORGOT PASSWORD
const forgotPassword = catchAsync(async (req: Request, res: Response) => {
	const body = req.body;

	await AuthService.forgotPassword(body);
	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: `OTP send successfully email: ${body.email}`,
		data: null,
	});
});

//& RESET PASSWORD
const resetPassword = catchAsync(async (req: Request, res: Response) => {
	const body = req.body;

	await AuthService.resetPassword(body);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "Password reset successfully",
		data: null,
	});
});

//& GOOGLE LOGIN
const googleLogin = catchAsync(async (req: Request, res: Response) => {
	const user = req.user;

	if (!user) {
		throw new AppError(
			httpStatus.INTERNAL_SERVER_ERROR,
			"Something Went wrong",
		);
	}

	const jwtPayload = {
		userId: (user as any).id,
		name: user.name,
		email: user.email,
		role: user.role,
	};

	const accessToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_access_secret,
		config.jwt_access_expires_in as SignOptions,
	);

	const refreshToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_refresh_secret,
		config.jwt_refresh_expires_in as SignOptions,
	);

	res.cookie(
		"accessToken",
		accessToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24),
	);
	res.cookie(
		"refreshToken",
		refreshToken,
		getAuthCookieOptions(1000 * 60 * 60 * 24 * 7),
	);

	const url = redirectUrl(user.role)

	res.redirect(`${config.frontend_url}/${url}`)

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: "Google login successful",
		data: {
			accessToken,
			refreshToken,
		},
	});
});

