import { Router } from "express";
import { zodValidation } from "../../middleware/zodValidation";
import { completeProfileZodSchema } from "./technician.validation";
import { auth } from "../../middleware/auth";
import { UserRole } from "../../../../generated/prisma/enums";
import { technicianController } from "./technician.controller";

const route = Router();

route.put(
	"/me/profile",
	zodValidation(completeProfileZodSchema),
	auth(UserRole.TECHNICIAN),
	technicianController.completeProfile,
);


route.get(
	'/all-technicians',
	technicianController.getAllTech
)

route.get(
	'/:technicianId',
	technicianController.getTechById
)



export const technicianRoutes = route;
