import bcrypt from "bcryptjs";
import { prisma } from "../../lib/prisma";
import { AppError } from "../../utils/appError";
import {
	IForgotPasswordPayload,
	ILoginUserPayload,
	IRegisterCustomerPayload,
	IResetPasswordPayload,
	IVerifyEmailPayload,
	RegisterRole,
} from "./auth.interface";
import httpStatus from "http-status";
import config from "../../config/env";
import crypto from "crypto";
import { redisClient } from "../../lib/redis";
import path from "path";
import ejs from "ejs";
import { transporter } from "../../lib/nodemailer";
import { UserStatus } from "../../../../generated/prisma/enums";
import { jwtUtils } from "../../utils/jwt";
import { JwtPayload, SignOptions } from "jsonwebtoken";
import { IRequestUser } from "../../interface";
import { formatTimeToHHmm } from "../../utils/utility";

const roleProfileMap: Record<RegisterRole, "customer" | "technician"> = {
	CUSTOMER: "customer",
	TECHNICIAN: "technician",
};

//& STORE REDIS AND OTP SEND
const registerOTP = async (payload: IRegisterCustomerPayload) => {
	const { name, password, role } = payload;

	const email = payload.email.trim().toLowerCase();

	const isUserExists = await prisma.user.findUnique({
		where: { email },
	});

	if (isUserExists) {
		throw new AppError(
			httpStatus.CONFLICT,
			"User with this email already exists",
		);
	}

	const hashedPassword = await bcrypt.hash(
		password,
		Number(config.bcrypt_salt_rounds),
	);

	const expirationTime = 5 * 60;
	const otp = crypto.randomInt(100000, 1000000);
	const otpKey = `register-otp: ${email}`;

	await redisClient.set(otpKey, otp, {
		expiration: {
			type: "EX",
			value: expirationTime,
		},
	});

	const registerKey = `register-data: ${email}`;
	const registerValue = {
		name,
		email,
		password: hashedPassword,
		role,
	};

	await redisClient.set(registerKey, JSON.stringify(registerValue), {
		expiration: {
			type: "EX",
			value: expirationTime,
		},
	});

	const templatePath = path.join(
		process.cwd(),
		"src/app/template/verification-otp.ejs",
	);

	const templateData = {
		name,
		otp,
		expire: expirationTime / 60,
		appName: config.app_name,
	};

	const html = await ejs.renderFile(templatePath, templateData);

	await transporter.sendMail({
		from: config.smtp_sender,
		to: email,
		subject: "Email Verification",
		html,
	});
};

//& EMAIL VERIFY AND ACCOUNT CREATE
const verifyEmail = async (payload: IVerifyEmailPayload) => {
	const { email, otp } = payload;

	const registerKey = `register-data: ${email}`;
	const redisData = await redisClient.get(registerKey);

	const otpKey = `register-otp: ${email}`;
	const redisOTP = await redisClient.get(otpKey);

	if (!redisData || !redisOTP) {
		throw new AppError(httpStatus.BAD_REQUEST, "Invalid Data from redis!");
	}

	const payloadData = JSON.parse(redisData) as IRegisterCustomerPayload;

	if (payloadData.email !== email) {
		throw new AppError(httpStatus.BAD_REQUEST, "Invalid email");
	}

	if (redisOTP !== otp) {
		throw new AppError(httpStatus.BAD_REQUEST, "OTP does not match!");
	}

	const isUser = await prisma.user.findUnique({
		where: { email },
	});

	if (isUser) {
		throw new AppError(httpStatus.CONFLICT, "Email alredy exist");
	}

	const profileKey = roleProfileMap[payloadData.role];

	const userCreated = await prisma.user.create({
		data: {
			name: payloadData.name,
			email: payloadData.email,
			password: payloadData.password,
			role: payloadData.role,
			emailVerified: true,
			status: "ACTIVE",
			[profileKey]: {
				create: {},
			},
		},
		omit: {
			password: true,
		},
		include: {
			[profileKey]: true,
		},
	});

	const templateData = {
		name: payloadData.name,
		appName: config.app_name,
	};

	const html = await ejs.renderFile(
		path.join(process.cwd(), "src/app/template/welcome.ejs"),
		templateData,
	);

	await transporter.sendMail({
		from: config.smtp_sender,
		to: payloadData.email,
		subject: `Welcome to ${config.app_name}`,
		html,
	});

	await redisClient.del([otpKey, registerKey]);

	const jwtPayload = {
		userId: userCreated.id,
		name: userCreated.name,
		email: userCreated.email,
		role: userCreated.role,
	};

	const accessToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_access_secret,
		config.jwt_access_expires_in as SignOptions,
	);

	const refreshToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_refresh_secret,
		config.jwt_refresh_expires_in as SignOptions,
	);

	return {
		accessToken,
		refreshToken,
		userCreated,
	};
};

//& LOGIN USER
const loginUser = async (payload: ILoginUserPayload) => {
	const { password } = payload;
	const email = payload.email.trim().toLowerCase();

	const isUser = await prisma.user.findUnique({
		where: { email },
	});

	if (!isUser) {
		throw new AppError(httpStatus.NOT_FOUND, "User not found");
	}

	if (isUser.status === "BLOCKED") {
		throw new AppError(httpStatus.FORBIDDEN, "User is blocked");
	}

	if (isUser.isDeleted || isUser.status === "DELETED") {
		throw new AppError(httpStatus.FORBIDDEN, "User is deleted");
	}

	const isPasswordMatched = await bcrypt.compare(
		password,
		isUser.password as string,
	);

	if (!isPasswordMatched) {
		throw new AppError(httpStatus.UNAUTHORIZED, "Invalid credentials");
	}

	const jwtPayload = {
		userId: isUser.id,
		name: isUser.name,
		email: isUser.email,
		role: isUser.role,
	};

	const accessToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_access_secret,
		config.jwt_access_expires_in as SignOptions,
	);

	const refreshToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_refresh_secret,
		config.jwt_refresh_expires_in as SignOptions,
	);


	const { password: pass, ...user } = isUser

	return {
		user,
		accessToken,
		refreshToken,
	};
};

//& GET ME
const getMe = async (user: IRequestUser) => {
	const dynamicInclude: Record<string, any> = {};
	const userRoleLower = user.role?.toLowerCase();

	if (userRoleLower && ["customer", "technician", "manager"].includes(userRoleLower)) {
		if (userRoleLower === "manager") {
			dynamicInclude["manager"] = {
				include: {
					region: true,
				},
			};
		} else if (userRoleLower === "technician") {
			dynamicInclude["technician"] = {
				include: {
					regions: true,
					availability: true,
					skills: {
						include: {
							category: true
						}
					}
				},
			};
		} else {
			dynamicInclude[userRoleLower] = true;
		}
	}

	const isUserExists = await prisma.user.findUnique({
		where: {
			id: user.userId,
		},
		include: dynamicInclude,
		omit: {
			password: true,
		},
	});

	if (!isUserExists) {
		throw new AppError(httpStatus.NOT_FOUND, "User not found");
	}

	const technician = (isUserExists as any).technician;
	if (technician?.availability) {
		technician.availability = technician.availability.map((slot: any) => ({
			...slot,
			startTime: formatTimeToHHmm(slot.startTime),
			endTime: formatTimeToHHmm(slot.endTime),
		}));
	}

	return isUserExists;
};


//& CREATE ACCESS TOKEN
const refreshToken = async (token: string) => {
	const verifiedRefreshToken = jwtUtils.verifyToken(
		token,
		config.jwt_refresh_secret,
	);

	if (!verifiedRefreshToken.success || !verifiedRefreshToken.data) {
		throw new AppError(
			httpStatus.UNAUTHORIZED,
			config.node_env === "development"
				? verifiedRefreshToken.error
				: "Invalid refresh token",
		);
	}

	const data = verifiedRefreshToken.data as JwtPayload;

	const user = await prisma.user.findUnique({
		where: { id: data.userId },
	});

	if (!user || user.isDeleted || user.status !== UserStatus.ACTIVE) {
		throw new AppError(
			httpStatus.UNAUTHORIZED,
			"User is inactive or not found",
		);
	}

	const jwtPayload = {
		userId: user.id,
		name: user.name,
		email: user.email,
		role: user.role,
	};

	const accessToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_access_secret,
		config.jwt_access_expires_in as SignOptions,
	);

	const refreshToken = jwtUtils.createToken(
		jwtPayload,
		config.jwt_refresh_secret,
		config.jwt_refresh_expires_in as SignOptions,
	);

	return {
		accessToken,
		refreshToken,
	};
};

//& FORGOT PASSWORD
const forgotPassword = async (payload: IForgotPasswordPayload) => {
	const { email } = payload;

	const isExistUser = await prisma.user.findUnique({
		where: { email },
	});

	if (!isExistUser) {
		throw new AppError(httpStatus.NOT_FOUND, "User does not exist");
	}

	if (isExistUser.status === "BLOCKED") {
		throw new AppError(httpStatus.FORBIDDEN, "User thas temporary blocked");
	}

	if (isExistUser.status === UserStatus.DELETED) {
		throw new AppError(httpStatus.FORBIDDEN, "user has deleted");
	}

	const otp = crypto.randomInt(100000, 1000000).toString();

	const expirationTime = 5 * 60;
	const key = `forgot-password-otp: ${isExistUser.email}`;
	await redisClient.set(key, otp, {
		expiration: {
			type: "EX",
			value: expirationTime,
		},
	});

	const templatePath = path.join(
		process.cwd(),
		"src/app/template/forgot-password-otp.ejs",
	);

	const templateData = {
		name: isExistUser.name,
		otp,
		expire: expirationTime / 60,
		appName: config.app_name,
	};

	const html = await ejs.renderFile(templatePath, templateData);

	await transporter.sendMail({
		from: config.smtp_sender,
		to: isExistUser.email,
		subject: "Forgot Password OTP",
		html,
	});
};

//& RESET PASSWORD
const resetPassword = async (payload: IResetPasswordPayload) => {
	const { email, otp, newPassword } = payload;

	const isExistUser = await prisma.user.findUnique({
		where: { email },
	});

	if (!isExistUser) {
		throw new AppError(httpStatus.NOT_FOUND, "User does not exist");
	}

	if (isExistUser.status === "BLOCKED") {
		throw new AppError(httpStatus.FORBIDDEN, "User thas temporary blocked");
	}

	if (isExistUser.status === UserStatus.DELETED) {
		throw new AppError(httpStatus.FORBIDDEN, "user has deleted");
	}

	const key = `forgot-password-otp: ${isExistUser.email}`;
	const redisOTP = await redisClient.get(key);

	if (!redisOTP) {
		throw new AppError(httpStatus.BAD_REQUEST, "Invalid OTP");
	}

	if (redisOTP !== otp) {
		throw new AppError(httpStatus.BAD_REQUEST, "OTP does not match");
	}

	const hashPass = await bcrypt.hash(
		newPassword,
		Number(config.bcrypt_salt_rounds),
	);

	await prisma.user.update({
		where: { email },
		data: {
			password: hashPass,
		},
	});

	const templateData = {
		name: isExistUser.name,
		appName: config.app_name,
	};

	const html = await ejs.renderFile(
		path.join(process.cwd(), "src/app/template/reset-password.ejs"),
		templateData,
	);

	await transporter.sendMail({
		from: config.smtp_sender,
		to: isExistUser.email,
		subject: "Reset Password",
		html,
	});

	await redisClient.del(key);
};


export const AuthService = {
	registerOTP,
	verifyEmail,
	loginUser,
	getMe,
	refreshToken,
	forgotPassword,
	resetPassword,
};
