import { Request, Response } from "express";
import { catchAsync } from "../../utils/catchAsync";
import { userService } from "./user.service";
import httpStatus from "http-status";
import { AppError } from "../../utils/appError";
import { IRequestUser } from "../../interface";
import { sendResponse } from "../../utils/sendResponse";

//& PROFILE IMAGE UPLOAD
const profileImageUpload = catchAsync(async (req: Request, res: Response) => {
	// console.log('request file ', req.file)

	if (!req.file) {
		throw new AppError(httpStatus.BAD_REQUEST, "No file uploaded");
	}

	const user = req.user as IRequestUser;

	const result = await userService.profileImageUpload(req.file, user);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: `profile updated successfully`,
		data: result,
	});
});

//& UPDATE CUSTOMER PROFILE
const udpateCustomer = catchAsync(async (req: Request, res: Response) => {
	const body = req.body;
	const user = req.user as IRequestUser;

	const result = await userService.updateCustomer(body, user);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: `customer profile updated successfully`,
		data: result,
	});
});


//& GET ALL USERS (ADMIN)
const getAllUsers = catchAsync(async (req: Request, res: Response) => {
	const query = req.query;

	const { users, meta } = await userService.getAllUsers(query);

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: `users retrive successfully`,
		data: users,
		meta,
	});
});


//& STATUS UPDATE
const statusUpdate = catchAsync(async (req: Request, res: Response) => {

	const data = req.body
	const userId = req.params.userId as string

	await userService.statusUpdate(data, userId)

	sendResponse(res, {
		statusCode: httpStatus.OK,
		success: true,
		message: `users status updated successfully`,
		data: null
	});
});


export const userController = {
	profileImageUpload,
	udpateCustomer,
	getAllUsers,
	statusUpdate,

};
